using System;using System.Collections.Generic;using System.IO;using System.IO.Pipes;using System.Text;using System.Threading;using System.Threading.Tasks;using System.Web.Script.Serialization;
namespace DragonCompanion {
public static class Json {
 public static string Encode(object o){return new JavaScriptSerializer{MaxJsonLength=16777216}.Serialize(o);}
 public static Dictionary<string,object> Decode(string s){return new JavaScriptSerializer{MaxJsonLength=16777216}.DeserializeObject(s) as Dictionary<string,object>;}
 public static object Get(Dictionary<string,object> d,string k){object v;return d!=null&&d.TryGetValue(k,out v)?v:null;}
 public static string Str(Dictionary<string,object>d,string k){return Get(d,k) as string;}
 public static Dictionary<string,object> Obj(Dictionary<string,object>d,string k){return Get(d,k) as Dictionary<string,object>;}
}
public sealed class DesktopLink:IDisposable {
 NamedPipeClientStream pipe;SemaphoreSlim writer=new SemaphoreSlim(1,1);Dictionary<string,TaskCompletionSource<Dictionary<string,object>>> pending=new Dictionary<string,TaskCompletionSource<Dictionary<string,object>>>();string client="initializing-client";bool disposed;bool broken;
 public event Action<Dictionary<string,object>> Broadcast; public bool Connected{get{return pipe!=null&&pipe.IsConnected&&!broken&&!disposed&&client!="initializing-client";}}
 public async Task Connect(){pipe=new NamedPipeClientStream(".","codex-ipc",PipeDirection.InOut,PipeOptions.Asynchronous);await Task.Run(()=>pipe.Connect(1500));var ignored=ReadLoop();var r=await Request("initialize",new{clientType="dragon-companion"},0);client=Json.Str(Json.Obj(r,"result"),"clientId");if(String.IsNullOrEmpty(client))throw new IOException("IPC 初始化失败");}
 async Task<byte[]> ReadExact(int n){var b=new byte[n];int o=0;while(o<n){int x=await pipe.ReadAsync(b,o,n-o);if(x==0)throw new EndOfStreamException();o+=x;}return b;}
 async Task ReadLoop(){try{while(!disposed){int n=BitConverter.ToInt32(await ReadExact(4),0);if(n<1||n>16777216)throw new IOException("IPC frame limit");var m=Json.Decode(Encoding.UTF8.GetString(await ReadExact(n)));string type=Json.Str(m,"type");if(type=="response"){TaskCompletionSource<Dictionary<string,object>> t;lock(pending){pending.TryGetValue(Json.Str(m,"requestId"),out t);}if(t!=null)t.TrySetResult(m);}else if(type=="client-discovery-request"){await Send(new{type="client-discovery-response",requestId=Json.Str(m,"requestId"),response=new{canHandle=false}});}else if(type=="broadcast"){var ev=Broadcast;if(ev!=null)ev(m);}}}catch(Exception e){broken=true;lock(pending){foreach(var p in pending.Values)p.TrySetException(new IOException("Codex 连接已断开",e));}}}
 async Task Send(object o){byte[] b=Encoding.UTF8.GetBytes(Json.Encode(o));await writer.WaitAsync();try{await pipe.WriteAsync(BitConverter.GetBytes(b.Length),0,4);await pipe.WriteAsync(b,0,b.Length);}finally{writer.Release();}}
 async Task<Dictionary<string,object>> Request(string method,object args,int version){if(method!="initialize"&&method!="thread-follower-read-model-settings")throw new InvalidOperationException("只读组件禁止修改 Codex");if(disposed)throw new ObjectDisposedException("DesktopLink");string id=Guid.NewGuid().ToString();var t=new TaskCompletionSource<Dictionary<string,object>>(TaskCreationOptions.RunContinuationsAsynchronously);lock(pending){pending.Add(id,t);}try{await Send(new{type="request",requestId=id,sourceClientId=client,version=version,method=method,@params=args,timeoutMs=3000});if(await Task.WhenAny(t.Task,Task.Delay(4500))!=t.Task)throw new TimeoutException("Codex 响应超时");var r=await t.Task;if(Json.Str(r,"resultType")!="success")throw new IOException(Json.Str(r,"error")??"Codex request failed");return r;}finally{lock(pending){pending.Remove(id);}}}
 public async Task<Dictionary<string,object>> ReadSettings(string id){var r=await Request("thread-follower-read-model-settings",new{conversationId=id},1);var settings=Json.Obj(Json.Obj(r,"result"),"settings");if(settings==null||!settings.ContainsKey("reasoningEffort")||!(Json.Get(settings,"model") is string))throw new IOException("桌面读取协议不兼容或聊天尚未就绪");return settings;}
 public void Dispose(){disposed=true;if(pipe!=null)pipe.Dispose();lock(pending){foreach(var p in pending.Values)p.TrySetException(new IOException("连接关闭"));pending.Clear();}}
}}
